import type { Ref } from 'react';
import { cn } from '../../utils/cn';
import { Badge, type BadgeProps } from '../badge/Badge';
import { DEFAULT_STATUSES, statusTagVariants, type StatusDefinition, type StatusTagVariantProps } from './statusTag.variants';

export interface StatusTagProps extends Omit<BadgeProps, 'tone' | 'dot' | 'onRemove' | 'removeLabel' | 'children'>, StatusTagVariantProps {
  ref?: Ref<HTMLSpanElement>;
  /** State key, looked up in `statuses` (then the generic defaults). */
  status: string;
  /** Extra or overriding state → { label, tone } entries. */
  statuses?: Record<string, StatusDefinition>;
  /** Overrides the mapped label. */
  label?: string;
}

/**
 * State pill with a dot. The state → tone mapping is a dictionary prop, merged over a small
 * set of generic states; unknown states fall back to a neutral tag showing the raw key.
 */
export function StatusTag({ status, statuses, label, uppercase, className, ...props }: StatusTagProps) {
  const def = statuses?.[status] ?? DEFAULT_STATUSES[status];
  const tone = def?.tone ?? 'neutral';
  return (
    <Badge tone={tone} dot data-status={status} className={cn(statusTagVariants({ uppercase }), className)} {...props}>
      {label ?? def?.label ?? status}
    </Badge>
  );
}

export { StatusTag, type StatusTagProps } from './StatusTag';
export { statusTagVariants, DEFAULT_STATUSES, type StatusDefinition, type StatusTagVariantProps } from './statusTag.variants';
export { doc as statusTagDoc } from './StatusTag.doc';

import { tv, type VariantProps } from '../../utils/tv';
import type { BadgeTone } from '../badge/badge.variants';

/** Layout on top of the Badge styles: optional uppercase kicker style. */
export const statusTagVariants = tv({
  base: 'tracking-wide',
  variants: {
    uppercase: { true: 'uppercase', false: '' },
  },
  defaultVariants: { uppercase: false },
});

export type StatusTagVariantProps = VariantProps<typeof statusTagVariants>;

export interface StatusDefinition {
  /** Visible label. */
  label: string;
  /** Badge tone the state maps to. */
  tone: BadgeTone;
}

/** Generic lifecycle states. Extend or override per product with the `statuses` prop. */
export const DEFAULT_STATUSES: Record<string, StatusDefinition> = {
  running: { label: 'Running', tone: 'success' },
  succeeded: { label: 'Succeeded', tone: 'success' },
  queued: { label: 'Queued', tone: 'info' },
  pending: { label: 'Pending', tone: 'neutral' },
  paused: { label: 'Paused', tone: 'neutral' },
  draft: { label: 'Draft', tone: 'neutral' },
  degraded: { label: 'Degraded', tone: 'warning' },
  failed: { label: 'Failed', tone: 'destructive' },
};

import type { ComponentDoc } from '../../doc';

export const doc: ComponentDoc = {
  name: 'StatusTag',
  group: 'Display',
  status: 'stable',
  description: 'State pill with a dot (running, queued, paused, failed, draft…). The state → tone mapping is a prop-driven dictionary merged over generic defaults, so products add their own states without touching the component.',
  tokens: ['success', 'success-text', 'info', 'warning', 'warning-text', 'destructive', 'destructive-text', 'muted-foreground'],
};
